import re
from ast import literal_eval

with open('/home/ctfplayer/ctf_files/extracted_challenge_data.txt') as f:
    data = f.read()

def parse_hex_list(s):
    # Parses [0x...., 0x...] to list of ints
    return [int(x, 16) for x in re.findall(r'0x[\da-fA-F]+', s)]

def parse():
    lines = data.splitlines()
    results = {}
    for l in lines:
        l = l.strip()
        if l.startswith('a0,a1') or l.startswith('A_l'):
            results['A_l'] = parse_hex_list(l)
        elif l.startswith('b0,b1') or l.startswith('B_l'):
            results['B_l'] = parse_hex_list(l)
        elif l.startswith('n1'):
            results['n1'] = int(re.findall(r'[0-9]+', l)[0])
        elif l.startswith('n2'):
            results['n2'] = int(re.findall(r'[0-9]+', l)[0])
        elif l.startswith('xs'):
            results['xs'] = parse_hex_list(l)
        elif l.startswith('zs'):
            results['zs'] = parse_hex_list(l)
        elif l.startswith('encflag'):
            encbytes = re.search(r"b'(.*)'", l)
            results['encflag'] = bytes.fromhex(encbytes.group(1).encode('utf-8').hex())
    # Fallback: try literal_eval for challenge dump
    if not results:
        try:
            challenge = literal_eval(data)
            results.update(challenge)
        except Exception:
            pass
    print(results)

if __name__ == '__main__':
    parse()

