import json
import re

FLAG_PATTERN = re.compile(rb'flag\{[ -~]{10,80}\}')

# Load encrypted flag value from challenge data file
def load_encflag(path):
    for line in open(path, 'rt'):
        if line.startswith('encflag = '):
            encflag = eval(line.split('=', 1)[1].strip())
            if isinstance(encflag, bytes):
                return encflag
    raise Exception("encflag not found")

# Load y_next candidate list
def load_candidates(path):
    with open(path, 'rt') as f:
        doc = json.load(f)
        return doc['y_next_candidates']

def xor_bytes(a: bytes, b: bytes) -> bytes:
    return bytes(x ^ y for x, y in zip(a, b))

def candidate_to_bytes(n, length):
    # big endian, fixed length
    return n.to_bytes(length, 'big')

def main():
    encflag = load_encflag('/home/ctfplayer/ctf_files/extracted_challenge_data.txt')
    candidates = load_candidates('/home/ctfplayer/y_next_candidates.json')
    found = 0
    for idx, y_next in enumerate(candidates):
        yb = candidate_to_bytes(y_next, len(encflag))
        pt = xor_bytes(encflag, yb)
        if FLAG_PATTERN.search(pt):
            print(f"Candidate #{idx}")
            print(f"y_next = {y_next}")
            print(f"Decoded: {pt}")
            found += 1
    if not found:
        print(f"No flag format match (flag{{...}}) found in {len(candidates)} y_next candidates.")

if __name__ == '__main__':
